insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1486c1', 'Guessing the Greatest (easy)', 'Codeforces', 'https://codeforces.com/problemset/problem/1486/C1', 1500, 'Interactive: hidden permutation of 1..n. Query `? l r` returns index of the second maximum on [l,r]. Find the index of the maximum in ≤20 queries.', 'First line n. Then interactive queries.', 'Print `! i` when found.', '$2 \le n \le 10^5$', '[]'::jsonb, 'O(log N)');
