insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1398d', 'Colored Rectangles', 'Codeforces', 'https://codeforces.com/problemset/problem/1398/D', 1800, 'You have sticks of three colors with lengths $R_i$, $G_j$, $B_k$. Repeatedly pick two different colors, form a rectangle with those sides, score area, and discard the sticks. Maximize total score.', 'The first line contains $r,g,b$ ($1 \le r,g,b \le 200$).

Then three lines with the stick lengths.', 'Print the maximum total area.', '$1 \le r,g,b \le 200$', '[{"input":"1 1 1\n5\n5\n5","output":"25"}]'::jsonb, 'O(N³)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1398d-a1', 'cf-1398d', '3D DP', ARRAY['Dynamic Programming']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['dp[i][j][k] max score using i/j/k longest remaining sticks of each color']::text[], 'Sort each color descending; transition by pairing two colors.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-minimum-euclidean-distance', 'Minimum Euclidean Distance', 'CSES', 'https://cses.fi/problemset/task/2194', 1800, 'Given a set of points in the two-dimensional plane, your task is to find the minimum Euclidean distance between two distinct points.

The Euclidean distance of points $(x_1,y_1)$ and $(x_2,y_2)$ is $\sqrt{(x_1-x_2)^2+(y_1-y_2)^2}$.

Input

The first input line has an integer $n$: the number of points.

After this, there are $n$ lines that describe the points. Each line has two integers $x$ and $y$. You may assume that each point is distinct.

Output

Print one integer: $d^2$ where $d$ is the minimum Euclidean distance (this ensures that the result is an integer).

Constraints

- $2 \le n \le 2 \cdot 10^5$

- $-10^9 \le x,y \le 10^9$

Example

Input:

4
2 1
4 4
1 2
6 3

Output:

2', 'The first input line has an integer $n$: the number of points.

After this, there are $n$ lines that describe the points. Each line has two integers $x$ and $y$. You may assume that each point is distinct.', 'Print one integer: $d^2$ where $d$ is the minimum Euclidean distance (this ensures that the result is an integer).', '- $2 \le n \le 2 \cdot 10^5$

- $-10^9 \le x,y \le 10^9$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-minimum-euclidean-distance-a1', 'cses-minimum-euclidean-distance', 'Closest pair D&C', ARRAY['Geometry','Divide & Conquer']::text[], ARRAY['Sweep Line','Sorting']::text[], ARRAY[]::text[], ARRAY['Classic closest-pair divide-and-conquer with strip check']::text[], 'Sort by x; recurse; check a strip of width δ sorted by y.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1245d', 'Shichikuji and Power Grid', 'Codeforces', 'https://codeforces.com/problemset/problem/1245/D', 1800, 'There are $n$ cities. You may build a power station in city $i$ for cost $c_i$, or connect $i$ and $j$ with a wire costing $(k_i+k_j)\cdot dist(i,j)$. Supply every city with electricity at minimum cost; output stations and connections.', 'The first line contains $n$ ($1 \le n \le 2000$).

Then $n$ coordinates, then array $c$, then array $k$.', 'Print total cost, the list of stations, and the list of wires.', '$1 \le n \le 2000$', '[{"input":"3\n2 3\n1 1\n3 2\n3 2 3\n3 2 3","output":"8\n3\n1 2 3\n0"}]'::jsonb, 'O(N²)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1245d-a1', 'cf-1245d', 'MST with virtual node', ARRAY['Graph Algorithms','Greedy']::text[], ARRAY['MST','DSU']::text[], ARRAY[]::text[], ARRAY['Virtual node 0 for power stations; MST on complete graph with station edges']::text[], 'Connect cities and a virtual power source; Kruskal yields stations + wires.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-finding-patterns', 'Finding Patterns', 'CSES', 'https://cses.fi/problemset/task/2102', 1800, 'Given a string and patterns, check for each pattern if it appears in the string.

Input

The first input line has a string of length $n$.

The next input line has an integer $k$: the number of patterns. Finally, there are $k$ lines that describe the patterns.

The string and the patterns consist of characters a–z.

Output

For each pattern, print "YES" if it appears in the string and "NO" otherwise.

Constraints

- $1 \le n \le 10^5$

- $1 \le k \le 5 \cdot 10^5$

- the total length of the patterns is at most $5 \cdot 10^5$

Example

Input:

aybabtu
3
bab
abc
ayba

Output:

YES
NO
YES', 'The first input line has a string of length $n$.

The next input line has an integer $k$: the number of patterns. Finally, there are $k$ lines that describe the patterns.

The string and the patterns consist of characters a–z.', 'For each pattern, print "YES" if it appears in the string and "NO" otherwise.', '- $1 \le n \le 10^5$

- $1 \le k \le 5 \cdot 10^5$

- the total length of the patterns is at most $5 \cdot 10^5$', '[]'::jsonb, 'O(N + M)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-finding-patterns-a1', 'cses-finding-patterns', 'Multi-pattern matching', ARRAY['String Algorithms']::text[], ARRAY['String Hashing']::text[], ARRAY['Trie']::text[], ARRAY['Aho-Corasick or suffix structure answers which patterns occur']::text[], 'Mark which of the k patterns appear as substrings of s.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-required-substring', 'Required Substring', 'CSES', 'https://cses.fi/problemset/task/1112', 1800, 'Your task is to calculate the number of strings of length $n$ having a given pattern of length $m$ as their substring. All strings consist of characters A–Z.

Input

The first input line has an integer $n$: the length of the final string.

The second line has a pattern of length $m$.

Output

Print the number of strings modulo $10^9+7$.

Constraints

- $1 \le n \le 1000$

- $1 \le m \le 100$

Example

Input:

6
ABCDB

Output:

52

Explanation: The final string will be of the form ABCDB$x$ or $x$ABCDB where $x$ is any character between A–Z.', 'The first input line has an integer $n$: the length of the final string.

The second line has a pattern of length $m$.', 'Print the number of strings modulo $10^9+7$.', '- $1 \le n \le 1000$

- $1 \le m \le 100$', '[]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-required-substring-a1', 'cses-required-substring', 'KMP automaton DP', ARRAY['String Algorithms','Dynamic Programming']::text[], ARRAY['KMP']::text[], ARRAY[]::text[], ARRAY['DP on position × KMP automaton state counting strings containing pattern']::text[], 'Count length-n strings over A–Z that contain the required substring.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-835d', 'Palindromic characteristics', 'Codeforces', 'https://codeforces.com/problemset/problem/835/D', 1800, 'A string is a $1$-palindrome if it is a palindrome. It is a $k$-palindrome ($k>1$) if it is a palindrome and its left half is a $(k-1)$-palindrome. Count how many substrings are $k$-palindromes for each $k$.', 'A single string $s$ ($1 \le |s| \le 5000$) of lowercase letters.', 'Print $|s|$ integers — counts for $k=1..|s|$.', '$1 \le |s| \le 5000$', '[{"input":"aaa","output":"6 3 1"}]'::jsonb, 'O(N²)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-835d-a1', 'cf-835d', 'Palindrome DP', ARRAY['String Algorithms','Dynamic Programming']::text[], ARRAY['String Hashing']::text[], ARRAY[]::text[], ARRAY['DP + palindromic checks via hash; k-palindrome halves']::text[], 'Classify every substring’s palindromic degree using hashing.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1213g', 'Path Queries', 'Codeforces', 'https://codeforces.com/problemset/problem/1213/G', 1800, 'You are given a weighted tree on $n$ vertices and $q$ queries. For each query $q_i$, count unordered pairs of vertices whose maximum edge on the path is $\le q_i$.', 'The first line contains $n$ and $q$ ($1 \le n,q \le 10^5$).

Then $n-1$ edges with weights.

Then $q$ integers $q_i$.', 'Print $q$ answers.', '$1 \le n,q \le 10^5$', '[{"input":"7 5\n1 2 1\n1 3 1\n2 4 2\n2 5 3\n3 6 2\n3 7 4\n1 2 3 4 5","output":"0 3 5 7 7"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1213g-a1', 'cf-1213g', 'Offline DSU', ARRAY['Graph Algorithms']::text[], ARRAY['DSU','Sorting']::text[], ARRAY[]::text[], ARRAY['Offline queries: add edges by increasing weight; DSU component sizes count pairs']::text[], 'Sort edges and queries; merge components while answering path-max ≤ q.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-range-updates-and-sums', 'Range Updates and Sums', 'CSES', 'https://cses.fi/problemset/task/1735', 1800, 'Your task is to maintain an array of $n$ values and efficiently process the following types of queries:

- Increase each value in range $[a,b]$ by $x$.

- Set each value in range $[a,b]$ to $x$.

- Calculate the sum of values in range $[a,b]$.

Input

The first input line has two integers $n$ and $q$: the array size and the number of queries.

The next line has $n$ values $t_1,t_2,\dots,t_n$: the initial contents of the array.

Finally, there are $q$ lines describing the queries. The format of each line is one of the following: "1 $a$ $b$ $x$",  "2 $a$ $b$ $x$", or "3 $a$ $b$".

Output

Print the answer to each sum query.

Constraints

- $1 \le n, q \le 2 \cdot 10^5$

- $1 \le t_i, x \le 10^6$

- $1 \le a \le b \le n$

Example

Input:

6 5
2 3 1 1 5 3
3 3 5
1 2 4 2
3 3 5
2 2 4 5
3 3 5

Output:

7
11
15', 'The first input line has two integers $n$ and $q$: the array size and the number of queries.

The next line has $n$ values $t_1,t_2,\dots,t_n$: the initial contents of the array.

Finally, there are $q$ lines describing the queries. The format of each line is one of the following: "1 $a$ $b$ $x$",  "2 $a$ $b$ $x$", or "3 $a$ $b$".', 'Print the answer to each sum query.', '- $1 \le n, q \le 2 \cdot 10^5$

- $1 \le t_i, x \le 10^6$

- $1 \le a \le b \le n$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-range-updates-and-sums-a1', 'cses-range-updates-and-sums', 'Lazy segtree', ARRAY['Ad-Hoc']::text[], ARRAY['Segment Tree']::text[], ARRAY[]::text[], ARRAY['Lazy segtree with range add and range assign + range sum']::text[], 'Compose assign/add lazy tags carefully for range sum queries.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-547b', 'Mike and Feet', 'Codeforces', 'https://codeforces.com/problemset/problem/547/B', 1800, 'Given an array of $n$ bear strengths, for every group size $k=1..n$ find the maximum of the minimums over all contiguous groups of size $k$.', 'The first line contains $n$ ($1 \le n \le 2\cdot 10^5$).

The second line contains $n$ integers $a_i$ ($1 \le a_i \le 10^9$).', 'Print $n$ integers — answers for $k=1..n$.', '$1 \le n \le 2\cdot 10^5$', '[{"input":"10\n1 2 3 4 5 4 3 2 1 6","output":"6 4 4 3 3 2 2 1 1 1"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-547b-a1', 'cf-547b', 'Span via mono stack', ARRAY['Greedy']::text[], ARRAY[]::text[], ARRAY['Monotonic Stack','Stack']::text[], ARRAY['For each position, span where it is minimum; update answers by span length']::text[], 'Nearest smaller left/right gives the max group size for each minimum.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1005e1', 'Median on Segments (Permutations Edition)', 'Codeforces', 'https://codeforces.com/problemset/problem/1005/E1', 1800, 'Given a permutation of $1..n$ and an integer $m$, count subsegments whose median is $m$.', 'The first line contains $n$ and $m$ ($1 \le m \le n \le 2\cdot 10^5$).

The second line contains the permutation.', 'Print the number of subsegments with median $m$.', '$1 \le n \le 2\cdot 10^5$', '[{"input":"5 4\n1 4 5 2 3","output":"4"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1005e1-a1', 'cf-1005e1', 'Median prefixes', ARRAY['Two Pointers','Math / Number Theory']::text[], ARRAY['Prefix Sums']::text[], ARRAY['Hash Map']::text[], ARRAY['Map values to -1/0/+1 around m; count prefixes with balanced transforms']::text[], 'Transform relative to m and count subarrays with the median property.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-counting-patterns', 'Counting Patterns', 'CSES', 'https://cses.fi/problemset/task/2103', 1800, 'Given a string and patterns, count for each pattern the number of positions where it appears in the string.

Input

The first input line has a string of length $n$.

The next input line has an integer $k$: the number of patterns. Finally, there are $k$ lines that describe the patterns.

The string and the patterns consist of characters a–z.

Output

For each pattern, print the number of positions.

Constraints

- $1 \le n \le 10^5$

- $1 \le k \le 5 \cdot 10^5$

- the total length of the patterns is at most $5 \cdot 10^5$

Example

Input:

aybabtu
3
bab
abc
a

Output:

1
0
2', 'The first input line has a string of length $n$.

The next input line has an integer $k$: the number of patterns. Finally, there are $k$ lines that describe the patterns.

The string and the patterns consist of characters a–z.', 'For each pattern, print the number of positions.', '- $1 \le n \le 10^5$

- $1 \le k \le 5 \cdot 10^5$

- the total length of the patterns is at most $5 \cdot 10^5$', '[]'::jsonb, 'O(N + M)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-counting-patterns-a1', 'cses-counting-patterns', 'Aho-Corasick', ARRAY['String Algorithms']::text[], ARRAY['String Hashing','KMP']::text[], ARRAY['Trie']::text[], ARRAY['Aho-Corasick occurrence counts for each pattern']::text[], 'Build a trie of patterns with failure links; stream the text and tally matches.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-pattern-positions', 'Pattern Positions', 'CSES', 'https://cses.fi/problemset/task/2104', 1800, 'Given a string and patterns, find for each pattern the first position (1-indexed) where it appears in the string.

Input

The first input line has a string of length $n$.

The next input line has an integer $k$: the number of patterns. Finally, there are $k$ lines that describe the patterns.

The string and the patterns consist of characters a–z.

Output

Print the first position for each pattern (or $-1$ if it does not appear at all).

Constraints

- $1 \le n \le 10^5$

- $1 \le k \le 5 \cdot 10^5$

- the total length of the patterns is at most $5 \cdot 10^5$

Example

Input:

aybabtu
3
bab
abc
a

Output:

3
-1
1', 'The first input line has a string of length $n$.

The next input line has an integer $k$: the number of patterns. Finally, there are $k$ lines that describe the patterns.

The string and the patterns consist of characters a–z.', 'Print the first position for each pattern (or $-1$ if it does not appear at all).', '- $1 \le n \le 10^5$

- $1 \le k \le 5 \cdot 10^5$

- the total length of the patterns is at most $5 \cdot 10^5$', '[]'::jsonb, 'O(N + M)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-pattern-positions-a1', 'cses-pattern-positions', 'First occurrence', ARRAY['String Algorithms']::text[], ARRAY['String Hashing','KMP']::text[], ARRAY['Trie']::text[], ARRAY['Report first occurrence index of each pattern (Aho-Corasick / SA)']::text[], 'Multi-pattern search returning the leftmost position for every pattern.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-counting-coprime-pairs', 'Counting Coprime Pairs', 'CSES', 'https://cses.fi/problemset/task/2417', 1800, 'Given a list of $n$ positive integers, your task is to count the number of pairs of integers that are coprime (i.e., their greatest common divisor is one).

Input

The first input line has an integer $n$: the number of elements.

The next line has $n$ integers $x_1,x_2,\dots,x_n$: the contents of the list.

Output

Print one integer: the answer for the task.

Constraints

- $1 \le n \le 10^5$

- $1 \le x_i \le 10^6$

Example

Input:

8
5 4 20 1 16 17 5 15

Output:

19', 'The first input line has an integer $n$: the number of elements.

The next line has $n$ integers $x_1,x_2,\dots,x_n$: the contents of the list.', 'Print one integer: the answer for the task.', '- $1 \le n \le 10^5$

- $1 \le x_i \le 10^6$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-counting-coprime-pairs-a1', 'cses-counting-coprime-pairs', 'Mobius sieve', ARRAY['Math / Number Theory']::text[], ARRAY['Sieve']::text[], ARRAY[]::text[], ARRAY['Mobius inversion over gcd; sieve μ and multiples counts']::text[], 'Count pairs with gcd 1 via μ(d) · C(cnt_d, 2) style sums.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-coin-grid', 'Coin Grid', 'CSES', 'https://cses.fi/problemset/task/1709', 1800, 'There is an $n \times n$ grid whose each square is empty or has a coin. On each move, you can remove all coins in a row or column.

What is the minimum number of moves after which the grid is empty?

Input

The first input line has an integer $n$: the size of the grid. The rows and columns are numbered $1,2,\dots,n$.

After this, there are $n$ lines describing the grid. Each line has $n$ characters: each character is either . (empty) or o (coin).

Output

First print an integer $k$: the minimum number of moves. After this, print $k$ lines describing the moves.

On each line, first print $1$ (row) or $2$ (column), and then the number of a row or column. You can print any valid solution.

Constraints

- $1 \le n \le 100$

Example

Input:

3
..o
o.o
...

Output:

2
1 2
2 3', 'The first input line has an integer $n$: the size of the grid. The rows and columns are numbered $1,2,\dots,n$.

After this, there are $n$ lines describing the grid. Each line has $n$ characters: each character is either . (empty) or o (coin).', 'First print an integer $k$: the minimum number of moves. After this, print $k$ lines describing the moves.

On each line, first print $1$ (row) or $2$ (column), and then the number of a row or column. You can print any valid solution.', '- $1 \le n \le 100$', '[]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-coin-grid-a1', 'cses-coin-grid', 'Bipartite cover', ARRAY['Flows / Matching','Graph Algorithms']::text[], ARRAY['BFS','DFS']::text[], ARRAY[]::text[], ARRAY['Minimum vertex cover on bipartite row-column graph of coins']::text[], 'Model coins as edges between rows and columns; Konig cover = matching.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-planets-queries-ii', 'Planets Queries II', 'CSES', 'https://cses.fi/problemset/task/1160', 1800, 'You are playing a game consisting of n planets. Each planet has a teleporter to another planet (or the planet itself).

You have to process $q$ queries of the form: You are now on planet $a$ and want to reach planet $b$. What is the minimum number of teleportations?

Input

The first input line contains two integers $n$ and $q$: the number of planets and queries. The planets are numbered $1,2,\ldots,n$.

The second line contains $n$ integers $t_1,t_2,\ldots,t_n$: for each planet, the destination of the teleporter.

Finally, there are $q$ lines describing the queries. Each line has two integers $a$ and $b$: you are now on planet $a$ and want to reach planet $b$.

Output

For each query, print the minimum number of teleportations. If it is not possible to reach the destination, print $-1$.

Constraints

- $1 \le n, q \le 2 \cdot 10^5$

- $1 \le a,b \le n$

Example

Input:

5 3
2 3 2 3 2
1 2
1 3
1 4

Output:

1
2
-1', 'The first input line contains two integers $n$ and $q$: the number of planets and queries. The planets are numbered $1,2,\ldots,n$.

The second line contains $n$ integers $t_1,t_2,\ldots,t_n$: for each planet, the destination of the teleporter.

Finally, there are $q$ lines describing the queries. Each line has two integers $a$ and $b$: you are now on planet $a$ and want to reach planet $b$.', 'For each query, print the minimum number of teleportations. If it is not possible to reach the destination, print $-1$.', '- $1 \le n, q \le 2 \cdot 10^5$

- $1 \le a,b \le n$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-planets-queries-ii-a1', 'cses-planets-queries-ii', 'Functional queries', ARRAY['Graph Algorithms']::text[], ARRAY['Binary Search','DFS']::text[], ARRAY['Queue']::text[], ARRAY['Functional graph: binary lifting + cycle handling for reachability queries']::text[], 'Answer whether a can reach b and the distance along unique outgoing edges.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-tree-isomorphism-i', 'Tree Isomorphism I', 'CSES', 'https://cses.fi/problemset/task/1700', 1800, 'Given two rooted trees, your task is to find out if they are isomorphic, i.e., it is possible to draw them so that they look the same.

Input

The first input line has an integer $t$: the number of tests. Then, there are $t$ tests described as follows:

The first line has an integer $n$: the number of nodes in both trees. The nodes are numbered $1,2,\dots,n$, and node $1$ is the root.

Then, there are $n-1$ lines describing the edges of the first tree, and finally $n-1$ lines describing the edges of the second tree.

Output

For each test, print "YES", if the trees are isomorphic, and "NO" otherwise.

Constraints

- $1 \le t \le 1000$

- $2 \le n \le 10^5$

- the sum of all values of $n$ is at most $10^5$

Example

Input:

2
3
1 2
2 3
1 2
1 3
3
1 2
2 3
1 3
3 2

Output:

NO
YES', 'The first input line has an integer $t$: the number of tests. Then, there are $t$ tests described as follows:

The first line has an integer $n$: the number of nodes in both trees. The nodes are numbered $1,2,\dots,n$, and node $1$ is the root.

Then, there are $n-1$ lines describing the edges of the first tree, and finally $n-1$ lines describing the edges of the second tree.', 'For each test, print "YES", if the trees are isomorphic, and "NO" otherwise.', '- $1 \le t \le 1000$

- $2 \le n \le 10^5$

- the sum of all values of $n$ is at most $10^5$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-tree-isomorphism-i-a1', 'cses-tree-isomorphism-i', 'AHU hashing', ARRAY['Graph Algorithms']::text[], ARRAY['DFS','Sorting']::text[], ARRAY['Hash Map']::text[], ARRAY['Rooted AHU tree hash: sort child hashes recursively']::text[], 'Compare two rooted trees via canonical parenthesized hashes.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-counting-tilings', 'Counting Tilings', 'CSES', 'https://cses.fi/problemset/task/2181', 1800, 'Your task is to count the number of ways you can fill an $n \times m$ grid using $1 \times 2$ and $2 \times 1$ tiles.

Input

The only input line has two integers $n$ and $m$.

Output

Print one integer: the number of ways modulo $10^9+7$.

Constraints

- $1 \le n \le 10$

- $1 \le m \le 1000$

Example

Input:

4 7

Output:

781', 'The only input line has two integers $n$ and $m$.', 'Print one integer: the number of ways modulo $10^9+7$.', '- $1 \le n \le 10$

- $1 \le m \le 1000$', '[]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-counting-tilings-a1', 'cses-counting-tilings', 'Profile DP', ARRAY['Bitmask / Bit DP','Dynamic Programming']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['Profile DP filling grid column-by-column with bitmasks']::text[], 'Enumerate vertical/horizontal tile placements transitioning masks between columns.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-295b', 'Greg and Graph', 'Codeforces', 'https://codeforces.com/problemset/problem/295/B', 1800, 'You are given an $n\times n$ adjacency matrix of a complete digraph. Vertices are deleted in a given order. Before each deletion, output the sum of shortest-path distances among remaining vertices.', 'The first line contains $n$ ($1 \le n \le 400$).

Then an $n\times n$ matrix.

Then a permutation of $1..n$ — deletion order.', 'Print $n$ numbers — the distance sums before each deletion.', '$1 \le n \le 400$', '[{"input":"4\n0 3 1 1\n3 0 1 1\n1 1 0 1\n1 1 1 0\n4 1 2 3","output":"17 7 2 0"}]'::jsonb, 'O(N³)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-295b-a1', 'cf-295b', 'Reverse Floyd', ARRAY['Graph Algorithms']::text[], ARRAY['Floyd-Warshall']::text[], ARRAY['2D Array']::text[], ARRAY['Add vertices in reverse deletion order; Floyd online']::text[], 'Run Floyd by inserting nodes backward; accumulate distance sums.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-448d', 'Multiplication Table', 'Codeforces', 'https://codeforces.com/problemset/problem/448/D', 1800, 'Consider the $n \times m$ multiplication table ($i\cdot j$ at cell $(i,j)$). Find the $k$-th smallest number in it.', 'A single line with $n$, $m$, and $k$ ($1 \le n,m \le 10^5$, $1 \le k \le n\cdot m$).', 'Print the $k$-th smallest entry.', '$1 \le n,m \le 10^5$', '[{"input":"2 3 4","output":"3"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-448d-a1', 'cf-448d', 'Count in table', ARRAY['Binary Search on Answer','Math / Number Theory']::text[], ARRAY['Binary Search','Ternary Search']::text[], ARRAY[]::text[], ARRAY['Binary search value x; count entries ≤ x by summing min(m, x/i)']::text[], 'Monotonic count of table entries ≤ mid; search the k-th.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-new-roads-queries', 'New Roads Queries', 'CSES', 'https://cses.fi/problemset/task/2101', 1800, 'There are $n$ cities in Byteland but no roads between them. However, each day, a new road will be built. There will be a total of $m$ roads.

Your task is to process $q$ queries of the form: "after how many days can we travel from city $a$ to city $b$ for the first time?"

Input

The first input line has three integers $n$, $m$ and $q$: the number of cities, roads and queries. The cities are numbered $1,2,\dots,n$.

After this, there are $m$ lines that describe the roads in the order they are built. Each line has two integers $a$ and $b$: there will be a road between cities $a$ and $b$.

Finally, there are $q$ lines that describe the queries. Each line has two integers $a$ and $b$: we want to travel from city $a$ to city $b$.

Output

For each query, print the number of days, or $-1$ if it is never possible.

Constraints

- $1 \le n, m, q \le 2 \cdot 10^5$

- $1 \le a,b \le n$

Example

Input:

5 4 3
1 2
2 3
1 3
2 5
1 3
3 4
3 5

Output:

2
-1
4', 'The first input line has three integers $n$, $m$ and $q$: the number of cities, roads and queries. The cities are numbered $1,2,\dots,n$.

After this, there are $m$ lines that describe the roads in the order they are built. Each line has two integers $a$ and $b$: there will be a road between cities $a$ and $b$.

Finally, there are $q$ lines that describe the queries. Each line has two integers $a$ and $b$: we want to travel from city $a$ to city $b$.', 'For each query, print the number of days, or $-1$ if it is never possible.', '- $1 \le n, m, q \le 2 \cdot 10^5$

- $1 \le a,b \le n$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-new-roads-queries-a1', 'cses-new-roads-queries', 'Offline MST queries', ARRAY['Graph Algorithms']::text[], ARRAY['DSU','Sorting','MST']::text[], ARRAY['Priority Queue']::text[], ARRAY['Offline Kruskal + LCT/persistent DSU for when two cities connect']::text[], 'Minimum max-edge on path equals MST bottleneck; answer with DSU time.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-intersection-points', 'Intersection Points', 'CSES', 'https://cses.fi/problemset/task/1740', 1800, 'Given $n$ horizontal and vertical line segments, your task is to calculate the number of their intersection points.

You can assume that no parallel line segments intersect, and no endpoint of a line segment is an intersection point.

Input

The first line has an integer $n$: the number of line segments.

Then there are $n$ lines describing the line segments. Each line has four integers: $x_1$, $y_1$, $x_2$ and $y_2$: a line segment begins at point $(x_1,y_1)$ and ends at point $(x_2,y_2)$.

Output

Print the number of intersection points.

Constraints

- $1 \le n \le 10^5$

- $-10^6 \le x_1 \le x_2 \le 10^6$

- $-10^6 \le y_1 \le y_2 \le 10^6$

- $(x_1,y_1) \neq (x_2,y_2)$

Example

Input:

3
2 3 7 3
3 1 3 5
6 2 6 6

Output:

2', 'The first line has an integer $n$: the number of line segments.

Then there are $n$ lines describing the line segments. Each line has four integers: $x_1$, $y_1$, $x_2$ and $y_2$: a line segment begins at point $(x_1,y_1)$ and ends at point $(x_2,y_2)$.', 'Print the number of intersection points.', '- $1 \le n \le 10^5$

- $-10^6 \le x_1 \le x_2 \le 10^6$

- $-10^6 \le y_1 \le y_2 \le 10^6$

- $(x_1,y_1) \neq (x_2,y_2)$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-intersection-points-a1', 'cses-intersection-points', 'Sweep + BIT', ARRAY['Geometry']::text[], ARRAY['Sorting','Segment Tree','Sweep Line']::text[], ARRAY['Fenwick Tree']::text[], ARRAY['Sweep line; fenwick counts horizontal segments stabbed by verticals']::text[], 'Count intersections among axis-aligned segments.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-palindrome-queries', 'Palindrome Queries', 'CSES', 'https://cses.fi/problemset/task/2420', 1800, 'You are given a string that consists of $n$ characters between a–z. The positions of the string are indexed $1,2,\dots,n$.

Your task is to process $m$ operations of the following types:

- Change the character at position $k$ to $x$

- Check if the substring from position $a$ to position $b$ is a palindrome

Input

The first input line has two integers $n$ and $m$: the length of the string and the number of operations.

The next line has a string that consists of $n$ characters.

Finally, there are $m$ lines that describe the operations. Each line is of the form "1 $k$ $x$" or "2 $a$ $b$".

Output

For each operation 2, print YES if the substring is a palindrome and NO otherwise.

Constraints

- $1 \le n, m \le 2 \cdot 10^5$

- $1 \le k \le n$

- $1 \le a \le b \le n$

Example

Input:

7 5
aybabtu
2 3 5
1 3 x
2 3 5
1 5 x
2 3 5

Output:

YES
NO
YES', 'The first input line has two integers $n$ and $m$: the length of the string and the number of operations.

The next line has a string that consists of $n$ characters.

Finally, there are $m$ lines that describe the operations. Each line is of the form "1 $k$ $x$" or "2 $a$ $b$".', 'For each operation 2, print YES if the substring is a palindrome and NO otherwise.', '- $1 \le n, m \le 2 \cdot 10^5$

- $1 \le k \le n$

- $1 \le a \le b \le n$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-palindrome-queries-a1', 'cses-palindrome-queries', 'Palindrome hashes', ARRAY['String Algorithms']::text[], ARRAY['String Hashing','Segment Tree']::text[], ARRAY['Fenwick Tree']::text[], ARRAY['Hash forward/backward with fenwick for point updates']::text[], 'Support updates and queries asking if a substring is a palindrome.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-all-palindromes', 'All Palindromes', 'CSES', 'https://cses.fi/problemset/task/3138', 1800, 'Given a string, calculate for each position the length of the longest palindrome that ends at that position.

Input

The only line contains a string of length $n$. Each character is one of a–z.

Output

Print $n$ numbers: the length of each palindrome.

Constraints

- $1 \le n \le 2 \cdot 10^5$

Example

Input:

ababbababaa

Output:

1 1 3 3 2 4 6 8 5 5 2', 'The only line contains a string of length $n$. Each character is one of a–z.', 'Print $n$ numbers: the length of each palindrome.', '- $1 \le n \le 2 \cdot 10^5$', '[]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-all-palindromes-a1', 'cses-all-palindromes', 'Manacher', ARRAY['String Algorithms']::text[], ARRAY['String Hashing']::text[], ARRAY['Deque']::text[], ARRAY['Manacher reports for each center the palindrome radii']::text[], 'For each index output the longest palindrome centered there.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-sos-bit-problem', 'SOS Bit Problem', 'CSES', 'https://cses.fi/problemset/task/1654', 1800, 'Given a list of $n$ integers, your task is to calculate for each element $x$:

- the number of elements $y$ such that $x \mid y = x$

- the number of elements $y$ such that $x \mathrel{\&} y = x$

- the number of elements $y$ such that $x \mathrel{\&} y \neq 0$

Input

The first line has an integer $n$: the size of the list.

The next line has $n$ integers $x_1,x_2,\dots,x_n$: the elements of the list.

Output

Print $n$ lines: for each element the required values.

Constraints

- $1 \le n \le 2 \cdot 10^5$

- $1 \le x_i \le 10^6$

Example

Input:

5
3 7 2 9 2

Output:

3 2 5
4 1 5
2 4 4
1 1 3
2 4 4', 'The first line has an integer $n$: the size of the list.

The next line has $n$ integers $x_1,x_2,\dots,x_n$: the elements of the list.', 'Print $n$ lines: for each element the required values.', '- $1 \le n \le 2 \cdot 10^5$

- $1 \le x_i \le 10^6$', '[]'::jsonb, 'O(2^N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-sos-bit-problem-a1', 'cses-sos-bit-problem', 'SOS DP', ARRAY['Bitmask / Bit DP']::text[], ARRAY[]::text[], ARRAY['1D Array']::text[], ARRAY['SOS DP over subsets/supersets of bitmasks']::text[], 'For each mask compute subset/superset population aggregates.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-subarray-sum-queries', 'Subarray Sum Queries', 'CSES', 'https://cses.fi/problemset/task/1190', 1800, 'There is an array consisting of $n$ integers. Some values of the array will be updated, and after each update, your task is to report the maximum subarray sum in the array.

Input

The first input line contains integers $n$ and $m$: the size of the array and the number of updates. The array is indexed $1,2,\ldots,n$.

The next line has $n$ integers: $x_1,x_2,\ldots,x_n$: the initial contents of the array.

Then there are $m$ lines describing the changes. Each line has two integers $k$ and $x$: the value at position $k$ becomes $x$.

Output

After each update, print the maximum subarray sum. Empty subarrays (with sum $0$) are allowed.

Constraints

- $1 \le n, m \le 2 \cdot 10^5$

- $-10^9 \le x_i \le 10^9$

- $1 \le k \le n$

- $-10^9 \le x \le 10^9$

Example

Input:

5 3
1 2 -3 5 -1
2 6
3 1
2 -2

Output:

9
13
6', 'The first input line contains integers $n$ and $m$: the size of the array and the number of updates. The array is indexed $1,2,\ldots,n$.

The next line has $n$ integers: $x_1,x_2,\ldots,x_n$: the initial contents of the array.

Then there are $m$ lines describing the changes. Each line has two integers $k$ and $x$: the value at position $k$ becomes $x$.', 'After each update, print the maximum subarray sum. Empty subarrays (with sum $0$) are allowed.', '- $1 \le n, m \le 2 \cdot 10^5$

- $-10^9 \le x_i \le 10^9$

- $1 \le k \le n$

- $-10^9 \le x \le 10^9$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-subarray-sum-queries-a1', 'cses-subarray-sum-queries', 'Subarray segtree', ARRAY['Ad-Hoc']::text[], ARRAY['Segment Tree']::text[], ARRAY[]::text[], ARRAY['Segtree node keeps total, pref, suf, best subarray sum']::text[], 'Point updates and global maximum subarray sum queries.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-bit-inversions', 'Bit Inversions', 'CSES', 'https://cses.fi/problemset/task/1188', 1800, 'There is a bit string consisting of $n$ bits. Then, there are some changes that invert one given bit. Your task is to report, after each change, the length of the longest substring whose each bit is the same.

Input

The first input line has a bit string consisting of $n$ bits. The bits are numbered $1,2,\ldots,n$.

The next line contains an integer $m$: the number of changes.

The last line contains $m$ integers $x_1,x_2,\ldots,x_m$ describing the changes.

Output

After each change, print the length of the longest substring whose each bit is the same.

Constraints

- $1 \le n \le 2 \cdot 10^5$

- $1 \le m \le 2 \cdot 10^5$

- $1 \le x_i \le n$

Example

Input:

001011
3
3 2 5

Output:

4 2 3

Explanation: The bit string first becomes 000011, then 010011, and finally 010001.', 'The first input line has a bit string consisting of $n$ bits. The bits are numbered $1,2,\ldots,n$.

The next line contains an integer $m$: the number of changes.

The last line contains $m$ integers $x_1,x_2,\ldots,x_m$ describing the changes.', 'After each change, print the length of the longest substring whose each bit is the same.', '- $1 \le n \le 2 \cdot 10^5$

- $1 \le m \le 2 \cdot 10^5$

- $1 \le x_i \le n$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-bit-inversions-a1', 'cses-bit-inversions', 'Run segtree', ARRAY['Ad-Hoc']::text[], ARRAY['Segment Tree']::text[], ARRAY['Ordered Set']::text[], ARRAY['Track runs of equal bits; updates flip and merge/split intervals']::text[], 'Maintain longest substring of equal bits under flips.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-apples-and-bananas', 'Apples and Bananas', 'CSES', 'https://cses.fi/problemset/task/2111', 1800, 'There are $n$ apples and $m$ bananas, and each of them has an integer weight between $1 \ldots k$. Your task is to calculate, for each weight $w$ between $2 \dots 2k$, the number of ways we can choose an apple and a banana whose combined weight is $w$.

Input

The first input line contains three integers $k$, $n$ and $m$: the number $k$, the number of apples and the number of bananas.

The next line contains $n$ integers $a_1,a_2,\ldots,a_n$: weight of each apple.

The last line contains $m$ integers $b_1,b_2,\ldots,b_m$: weight of each banana.

Output

For each integer $w$ between $2 \ldots 2k$ print the number of ways to choose an apple and a banana whose combined weight is $w$.

Constraints

- $1 \le k,n,m \le 2 \cdot 10^5$

- $1 \le a_i \le k$

- $1 \le b_i \le k$

Example

Input:

5 3 4
5 2 5
4 3 2 3

Output:

0 0 1 2 1 2 4 2 0

Explanation: For example for $w$ = $8$ there are $4$ different ways: we can pick an apple of weight $5$ in two different ways and a banana of weight $3$ in two different ways.', 'The first input line contains three integers $k$, $n$ and $m$: the number $k$, the number of apples and the number of bananas.

The next line contains $n$ integers $a_1,a_2,\ldots,a_n$: weight of each apple.

The last line contains $m$ integers $b_1,b_2,\ldots,b_m$: weight of each banana.', 'For each integer $w$ between $2 \ldots 2k$ print the number of ways to choose an apple and a banana whose combined weight is $w$.', '- $1 \le k,n,m \le 2 \cdot 10^5$

- $1 \le a_i \le k$

- $1 \le b_i \le k$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-apples-and-bananas-a1', 'cses-apples-and-bananas', 'NTT convolution', ARRAY['Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['FFT/NTT convolution of apple and banana count polynomials']::text[], 'Count ways to buy a apples and b bananas with given multiplicities.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-cut-and-paste', 'Cut and Paste', 'CSES', 'https://cses.fi/problemset/task/2072', 1800, 'Given a string, your task is to process operations where you cut a substring and paste it to the end of the string. What is the final string after all the operations?

Input

The first input line has two integers $n$ and $m$: the length of the string and the number of operations. The characters of the string are numbered $1,2,\dots,n$.

The next line has a string of length $n$ that consists of characters A–Z.

Finally, there are $m$ lines that describe the operations. Each line has two integers $a$ and $b$: you cut a substring from position $a$ to position $b$.

Output

Print the final string after all the operations.

Constraints

- $1 \le n, m \le 2 \cdot 10^5$

- $1 \le a \le b \le n$

Example

Input:

7 2
AYBABTU
3 5
3 5

Output:

AYABTUB', 'The first input line has two integers $n$ and $m$: the length of the string and the number of operations. The characters of the string are numbered $1,2,\dots,n$.

The next line has a string of length $n$ that consists of characters A–Z.

Finally, there are $m$ lines that describe the operations. Each line has two integers $a$ and $b$: you cut a substring from position $a$ to position $b$.', 'Print the final string after all the operations.', '- $1 \le n, m \le 2 \cdot 10^5$

- $1 \le a \le b \le n$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-cut-and-paste-a1', 'cses-cut-and-paste', 'Implicit treap', ARRAY['Ad-Hoc']::text[], ARRAY[]::text[], ARRAY['Deque','Stack']::text[], ARRAY['Implicit treap / rope cut substring and paste at position']::text[], 'Support cut-and-paste operations on a string.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-substring-reversals', 'Substring Reversals', 'CSES', 'https://cses.fi/problemset/task/2073', 1800, 'Given a string, your task is to process operations where you reverse a substring of the string. What is the final string after all the operations?

Input

The first input line has two integers $n$ and $m$: the length of the string and the number of operations. The characters of the string are numbered $1,2,\dots,n$.

The next line has a string of length $n$ that consists of characters A–Z.

Finally, there are $m$ lines that describe the operations. Each line has two integers $a$ and $b$: you reverse a substring from position $a$ to position $b$.

Output

Print the final string after all the operations.

Constraints

- $1 \le n, m \le 2 \cdot 10^5$

- $1 \le a \le b \le n$

Example

Input:

7 2
AYBABTU
3 4
4 7

Output:

AYAUTBB', 'The first input line has two integers $n$ and $m$: the length of the string and the number of operations. The characters of the string are numbered $1,2,\dots,n$.

The next line has a string of length $n$ that consists of characters A–Z.

Finally, there are $m$ lines that describe the operations. Each line has two integers $a$ and $b$: you reverse a substring from position $a$ to position $b$.', 'Print the final string after all the operations.', '- $1 \le n, m \le 2 \cdot 10^5$

- $1 \le a \le b \le n$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-substring-reversals-a1', 'cses-substring-reversals', 'Treap reverse', ARRAY['Ad-Hoc']::text[], ARRAY[]::text[], ARRAY['Deque']::text[], ARRAY['Implicit treap with reverse lazy tags']::text[], 'Reverse substrings online and print the final string.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1486c2', 'Guessing the Greatest (hard version)', 'Codeforces', 'https://codeforces.com/problemset/problem/1486/C2', 1800, 'Interactive: array of $n$ distinct numbers. Query $?\ l\ r$ returns the index of the second maximum on $[l,r]$. Find the index of the global maximum in $\le 20$ queries.', 'First the integer $n$ ($2 \le n \le 10^5$). Then interactive queries.', 'Print `! x` — the index of the maximum.', 'At most 20 queries', '[]'::jsonb, 'O(log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1486c2-a1', 'cf-1486c2', 'Interactive binary search', ARRAY['Interactive','Binary Search on Answer']::text[], ARRAY['Binary Search']::text[], ARRAY[]::text[], ARRAY['Query second-max to binary search which side holds the maximum']::text[], 'Locate the second maximum first, then binary search the segment containing the max.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1083a', 'The Fair Nut and the Best Path', 'Codeforces', 'https://codeforces.com/problemset/problem/1083/A', 1800, 'A tree with vertex fuel $w_v$ and edge costs. Maximize $w_u + w_v - dist(u,v)$ over pairs (path fuel net).', 'Tree of $n$ vertices with fuels and weighted edges.', 'Print the maximum value.', '$1 \le n \le 3\cdot 10^5$', '[{"input":"3\n1 3 3\n1 2 2\n1 3 2","output":"3"}]'::jsonb, 'O(N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1083a-a1', 'cf-1083a', 'Tree path DP', ARRAY['Graph Algorithms','Dynamic Programming']::text[], ARRAY['DFS']::text[], ARRAY[]::text[], ARRAY['Tree DP keeping best two child downward paths']::text[], 'For each node combine best downward fuel paths minus edge costs.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-558c', 'Amr and Chemistry', 'Codeforces', 'https://codeforces.com/problemset/problem/558/C', 1800, 'You have $n$ positive integers. In one move pick an element and replace it by $\lfloor x/2 \rfloor$ or $2x$. Minimize total moves so all elements become equal.', 'First line $n$ ($1 \le n \le 10^5$).

Second line $n$ integers $a_i$ ($1 \le a_i \le 10^5$).', 'Print the minimum number of moves.', '$1 \le n \le 10^5$', '[{"input":"3\n4 8 2","output":"2"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-558c-a1', 'cf-558c', 'Number BFS', ARRAY['Greedy','Math / Number Theory']::text[], ARRAY['BFS']::text[], ARRAY['Queue']::text[], ARRAY['All values can be reduced to a common core by /2 and *2; BFS costs on the number line']::text[], 'Try each possible final value reachable by shifts; sum min ops from each a_i.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cf-1117c', 'Magic Ship', 'Codeforces', 'https://codeforces.com/problemset/problem/1117/C', 1800, 'A ship starts at $(x1,y1)$ and must reach $(x2,y2)$. Each day wind blows U/D/L/R in a cycle of length $n$, then you may also move one step or stay. Find minimum days or $-1$.', 'Coordinates, then $n$ and the wind string.', 'Print the minimum days or $-1$.', '$1 \le n \le 10^5$', '[{"input":"0 0\n4 6\n3\nUUU","output":"5"}]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cf-1117c-a1', 'cf-1117c', 'Binary search time', ARRAY['Binary Search on Answer','Geometry']::text[], ARRAY['Binary Search']::text[], ARRAY[]::text[], ARRAY['Binary search days; wind prefix must leave a Manhattan remainder ≤ days']::text[], 'After t days of cyclic wind, check if remaining distance is achievable.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-corner-subgrid-check', 'Corner Subgrid Check', 'CSES', 'https://cses.fi/problemset/task/3360', 1800, 'You are given a grid of letters. Your task is to find subgrids whose height and width is at least two and all the corners have the same letter.

For each letter, check if there is a valid subgrid whose corners have that letter.

Input

The first line has two integers $n$ and $k$: the size of the grid and the number of letters. The letters are the first $k$ uppercase letters.

After this, there are $n$ lines that describe the grid. Each line has $n$ letters.

Output

Print $k$ lines: for each letter, YES if there is a valid subgrid and NO otherwise.

Constraints

- $1 \le n \le 3000$

- $1 \le k \le 26$

Example

Input:

4 5
AAAA
CBBC
CBBE
AAAA

Output:

YES
YES
NO
NO
NO', 'The first line has two integers $n$ and $k$: the size of the grid and the number of letters. The letters are the first $k$ uppercase letters.

After this, there are $n$ lines that describe the grid. Each line has $n$ letters.', 'Print $k$ lines: for each letter, YES if there is a valid subgrid and NO otherwise.', '- $1 \le n \le 3000$

- $1 \le k \le 26$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-corner-subgrid-check-a1', 'cses-corner-subgrid-check', 'Standard approach', ARRAY['Divide & Conquer','Brute Force']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['CSES Advanced Techniques: apply standard techniques for “Corner Subgrid Check”.']::text[], 'Auto-tagged from CSES section “Advanced Techniques”. Review tags after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-corner-subgrid-count', 'Corner Subgrid Count', 'CSES', 'https://cses.fi/problemset/task/2137', 1800, 'You are given an $n \times n$ grid whose each square is either black or white. A subgrid is called beautiful if its height and width is at least two and all of its corners are black. How many beautiful subgrids are there within the given grid?

Input

The first input line has an integer $n$: the size of the grid.

Then there are $n$ lines describing the grid: 1 means that a square is black and 0 means it is white.

Output

Print the number of beautiful subgrids.

Constraints

- $1 \le n \le 3000$

Example

Input:

5
00010
11111
00110
11001
00010

Output:

4', 'The first input line has an integer $n$: the size of the grid.

Then there are $n$ lines describing the grid: 1 means that a square is black and 0 means it is white.', 'Print the number of beautiful subgrids.', '- $1 \le n \le 3000$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-corner-subgrid-count-a1', 'cses-corner-subgrid-count', 'Standard approach', ARRAY['Divide & Conquer','Brute Force']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['CSES Advanced Techniques: apply standard techniques for “Corner Subgrid Count”.']::text[], 'Auto-tagged from CSES section “Advanced Techniques”. Review tags after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-filled-subgrid-count-i', 'Filled Subgrid Count I', 'CSES', 'https://cses.fi/problemset/task/3413', 1800, 'You are given a grid of letters. Your task is to calculate, for each letter, the number of square subgrids whose each letter is the same.

Input

The first line has two integers $n$ and $k$: the size of the grid and the number of letters. The letters are the first $k$ uppercase letters.

After this, there are $n$ lines that describe the grid. Each line has $n$ letters.

Output

Print $k$ lines: for each letter, the number of subgrids.

Constraints

- $1 \le n \le 3000$

- $1 \le k \le 26$

Example

Input:

5 3
ABBBC
BBBBC
BCAAA
AAAAA
AAAAA

Output:

21
10
3', 'The first line has two integers $n$ and $k$: the size of the grid and the number of letters. The letters are the first $k$ uppercase letters.

After this, there are $n$ lines that describe the grid. Each line has $n$ letters.', 'Print $k$ lines: for each letter, the number of subgrids.', '- $1 \le n \le 3000$

- $1 \le k \le 26$', '[]'::jsonb, 'O(N²)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-filled-subgrid-count-i-a1', 'cses-filled-subgrid-count-i', 'Standard approach', ARRAY['Dynamic Programming','Math / Number Theory']::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY['CSES Counting Problems: apply standard techniques for “Filled Subgrid Count I”.']::text[], 'Auto-tagged from CSES section “Counting Problems”. Review tags after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-reachability-queries', 'Reachability Queries', 'CSES', 'https://cses.fi/problemset/task/2143', 1800, 'A directed graph consists of $n$ nodes and $m$ edges. The edges are numbered $1,2,\dots,n$.

Your task is to answer $q$ queries of the form "can you reach node $b$ from node $a$?"

Input

The first input line has three integers $n$, $m$ and $q$: the number of nodes, edges and queries.

Then there are $m$ lines describing the edges. Each line has two distinct integers $a$ and $b$: there is an edge from node $a$ to node $b$.

Finally there are $q$ lines describing the queries. Each line consists of two integers $a$ and $b$: "can you reach node $b$ from node $a$?"

Output

Print the answer for each query: either "YES" or "NO".

Constraints

- $1 \le n \le 5 \cdot 10^4$

- $1 \le m,q \le 10^5$

Example

Input:

4 4 3
1 2
2 3
3 1
4 3
1 3
1 4
4 1

Output:

YES
NO
YES', 'The first input line has three integers $n$, $m$ and $q$: the number of nodes, edges and queries.

Then there are $m$ lines describing the edges. Each line has two distinct integers $a$ and $b$: there is an edge from node $a$ to node $b$.

Finally there are $q$ lines describing the queries. Each line consists of two integers $a$ and $b$: "can you reach node $b$ from node $a$?"', 'Print the answer for each query: either "YES" or "NO".', '- $1 \le n \le 5 \cdot 10^4$

- $1 \le m,q \le 10^5$', '[]'::jsonb, 'O(N log N)');
insert into public.solution_approaches (id, problem_id, approach_name, paradigms, algorithms, data_structures, key_insights, editorial_summary_md) values ('cses-reachability-queries-a1', 'cses-reachability-queries', 'Standard approach', ARRAY['Divide & Conquer','Brute Force']::text[], ARRAY['SCC','DFS']::text[], ARRAY[]::text[], ARRAY['CSES Advanced Techniques: apply standard techniques for “Reachability Queries”.']::text[], 'Auto-tagged from CSES section “Advanced Techniques”. Review tags after solving.');
insert into public.problems (id, title, source, url, difficulty_rating, statement_md, input_format_md, output_format_md, constraints_text, sample_io, target_complexity) values ('cses-filled-subgrid-count-ii', 'Filled Subgrid Count II', 'CSES', 'https://cses.fi/problemset/task/3414', 1800, 'You are given a grid of letters. Your task is to calculate, for each letter, the number of rectangular subgrids whose each letter is the same.

Input

The first line has two integers $n$ and $k$: the size of the grid and the number of letters. The letters are the first $k$ uppercase letters.

After this, there are $n$ lines that describe the grid. Each line has $n$ letters.

Output

Print $k$ lines: for each letter, the number of subgrids.

Constraints

- $1 \le n \le 3000$

- $1 \le k \le 26$

Example

Input:

5 3
ABBBC
BBBBC
BCAAA
AAAAA
AAAAA

Output:

64
24
4', 'The first line has two integers $n$ and $k$: the size of the grid and the number of letters. The letters are the first $k$ uppercase letters.

After this, there are $n$ lines that describe the grid. Each line has $n$ letters.', 'Print $k$ lines: for each letter, the number of subgrids.', '- $1 \le n \le 3000$

- $1 \le k \le 26$', '[]'::jsonb, 'O(N²)');
